'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 mountain:'<path d="m3 19 7-12 4 7 3-5 4 10H3Z"/><path d="m8 10 2 3 2-3"/>',
 people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',
 buddy:'<circle cx="7" cy="8" r="3"/><circle cx="17" cy="8" r="3"/><path d="M2 21v-3a5 5 0 0 1 10 0v3m0-3a5 5 0 0 1 10 0v3"/>',
 compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',
 mind:'<path d="M9 19H6a3 3 0 0 1-3-3v-4a4 4 0 0 1 3-4 4 4 0 0 1 6-4 4 4 0 0 1 6 4 4 4 0 0 1 3 4v4a3 3 0 0 1-3 3h-3M12 4v17M7 12h5m5 3h-5"/>',
 balance:'<circle cx="12" cy="12" r="8"/><path d="M12 4c-6 2 6 6 0 8s6 6 0 8"/><circle cx="12" cy="8" r=".7"/><circle cx="12" cy="16" r=".7"/>',
 shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 leaf:'<path d="M20 4C4 2 2 14 7 18S22 15 20 4ZM5 21l10-11"/>',
 coffee:'<path d="M4 8h12v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V8Zm12 1h2a3 3 0 0 1 0 6h-2M7 2v3m4-3v3"/>',
 body:'<path d="M5 7v10M2 9v6m17-8v10m3-8v6M5 12h14"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.compass}</svg>`;
const categories = ['Hiking','Deporte','Camping','Café y charla','Bienestar','Voluntariado'];
const pillarData = [
 {name:'Body',icon:'body',text:'Fortaleza que se construye. Movimiento, alimentación y hábitos con intención.',label:'Poné tu cuerpo en movimiento',practice:'Un primer paso sostenible',description:'Elegí una actividad que disfrutes y un momento realista de tu semana. Empezar con algo que puedas repetir vale más que un plan perfecto.',steps:['Elegí caminar, entrenar o una actividad que ya disfrutes.','Reservá un momento concreto en tu semana.','Adaptá la intensidad a tu experiencia y a cómo te sentís.','Buscá compañía si eso te ayuda a sostenerlo.']},
 {name:'Mind',icon:'mind',text:'Espacio para pensar mejor. Reflexión, curiosidad y claridad mental.',label:'Dale espacio a lo que pensás',practice:'Cinco minutos para vos',description:'Bajá un cambio y observá tu día sin juzgarlo. No hace falta escribir algo brillante: alcanza con escribir algo honesto.',steps:['Anotá algo que hoy te dio energía.','Reconocé algo que te la quitó.','Elegí una cosa pequeña que querés hacer distinto mañana.']},
 {name:'Balance',icon:'balance',text:'Volver a tu centro. Pausa, presencia y una vida con más equilibrio.',label:'Encontrá tu propio ritmo',practice:'Una pausa con intención',description:'No todo avance se mide en velocidad. Reservá un momento sin pantallas para reconocer cómo estás.',steps:['Buscá un lugar tranquilo y cómodo.','Respirá de manera natural, sin forzar.','Observá qué necesitás ahora: descanso, movimiento o compañía.','Elegí una acción pequeña que responda a esa necesidad.']},
 {name:'Purpose',icon:'compass',text:'Una dirección propia. Objetivos que importan y pasos que te acercan.',label:'Avanzá hacia lo que importa',practice:'De intención a próximo paso',description:'Una dirección clara puede empezar con una pregunta simple: ¿a qué me gustaría dedicar más atención?',steps:['Elegí un área de tu vida que quieras cuidar.','Escribí por qué te importa.','Definí un paso concreto que puedas dar esta semana.','Hablalo con alguien que pueda acompañarte.']}
];
const state = { user:null, profile:null, admin:false, routeVersion:0, filters:{q:'',city:'',category:''}, dialogContext:null, toastTimer:null };
const db = window.supabase?.createClient(window.TREKSOR_CONFIG.url,window.TREKSOR_CONFIG.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'treksor-web-auth'}});
const main = $('#main');
function toast(message){ $('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000); }
function errorText(error){
 const message=String(error?.message||error||'');
 if(error?.code==='23505') return 'Ya existe esta solicitud o inscripción. Revisá Mi espacio para continuar.';
 if(error?.code==='42501') return 'No tenés permiso para realizar esta acción. Comprobá tu sesión y el estado de la solicitud.';
 if(message.includes('Invalid login credentials')) return 'El correo o la contraseña no coinciden.';
 if(message.includes('Email not confirmed')) return 'Confirmá tu correo antes de entrar.';
 if(message.toLowerCase().includes('rate limit')) return 'Se hicieron varios intentos seguidos. Esperá unos minutos y volvé a intentar.';
 if(message.includes('fetch')||message.includes('network')) return 'No pudimos conectar. Comprobá tu conexión y volvé a intentar.';
 if(message.includes('Password')) return 'La contraseña no cumple los requisitos de la cuenta. Usá al menos 8 caracteres.';
 if(error?.code==='23514') return 'Revisá los datos y la longitud de los campos.';
 return 'No pudimos completar la acción. Volvé a intentar en unos minutos.';
}
async function query(request){const {data,error}=await request;if(error)throw error;return data;}
function route(){const path=(location.hash.replace(/^#/,'')||'/').split('?')[0];return path;}
function go(path){if(route()===path)render();else location.hash=path;}
function initials(name){return String(name||'T').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function avatar(name,large=false){return `<span class="avatar${large?' large':''}">${esc(initials(name))}</span>`;}
function date(value){return new Intl.DateTimeFormat('es',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}
function btn(text,action,id='',extra=''){return `<button class="button small ${extra}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${text}</button>`;}
function empty(title,description,action='',symbol='compass'){return `<div class="empty"><div class="empty-visual">${icon(symbol)}</div><div><h3>${title}</h3><p>${description}</p>${action}</div></div>`;}
function pageTop(eyebrow,title,description,action=''){return `<section class="page-top"><div class="wrap"><div class="eyebrow">${eyebrow}</div><div class="page-top-row"><div><h1>${title}</h1><p>${description}</p></div>${action}</div></div></section>`;}
function openDialog(title,content,eyebrow='TREKSOR'){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${title}</h2>${content}`;if(!d.open)d.showModal();}
function closeDialog(){ $('#dialog').close();state.dialogContext=null; }
function formError(form,error){const el=$('.form-error',form);if(el){el.textContent=errorText(error);el.setAttribute('role','alert');}else toast(errorText(error));}
function needUser(){if(state.user)return true;authDialog();return false;}
function needProfile(){if(!needUser())return false;if(!state.profile){profileDialog();return false;}return true;}
function updateNav(){const path=route();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='home'?path==='/':path.includes(a.dataset.nav)));$('#account-nav').innerHTML=state.user?`<a class="button small ghost" href="#/espacio">Mi espacio ↗</a>`:`<button class="button small ghost" data-action="login">Entrar ↗</button>`;}
async function loadProfile(){if(!state.user){state.profile=null;state.admin=false;return;}const [profile,admin]=await Promise.all([query(db.from('web_profiles').select('*').eq('user_id',state.user.id).maybeSingle()),query(db.from('admin_members').select('user_id').eq('user_id',state.user.id).maybeSingle())]);state.profile=profile;state.admin=!!admin;}
function renderHome(){return `
 <section class="hero"><img class="hero-photo" src="/assets/forest.jpg" alt="Personas caminando por un sendero entre montañas y bosque" fetchpriority="high"><span class="vertical-note">EL CAMINO EMPIEZA CON VOS</span><div class="wrap"><div class="hero-copy"><div class="eyebrow">UNA VIDA CON MÁS INTENCIÓN</div><h1>Tu camino.<br>Tu gente.<br><em>Tu mejor versión.</em></h1><p>Un espacio para fortalecer tu cuerpo, encontrar claridad y conectar con personas que también quieren avanzar.</p><div class="hero-actions"><a class="button" href="#/community">Encontrá tu comunidad <span>↗</span></a><a class="text-link" href="#/ecosistema">Descubrí Treksor <span>→</span></a></div></div></div><div class="hero-foot"><span>BODY &nbsp; / &nbsp; MIND &nbsp; / &nbsp; BALANCE &nbsp; / &nbsp; PURPOSE</span><span>UN POCO MÁS LEJOS. UN POCO MÁS CERCA DE VOS.</span></div></section>
 <section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">CUATRO PILARES. UN MISMO CAMINO.</div><h2>Crecer en todas<br>tus dimensiones.</h2></div><p>Tu bienestar no vive en compartimentos.<br>Treksor conecta movimiento, mente, equilibrio y propósito para que encuentres tu propia dirección.</p></div><div class="pillars">${pillarData.map((p,i)=>`<article class="pillar"><div class="pillar-number">0${i+1}</div><span class="pillar-icon">${icon(p.icon)}</span><h3>${p.name}</h3><p>${p.text}</p><a class="text-link" href="#/ecosistema">Explorar <span>↗</span></a></article>`).join('')}</div></div></section>
 <section class="section muted-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">COMMUNITY</div><h2>Compartir también<br>es parte del camino.</h2></div><p>No hay una sola forma de conectar. Encontrá un grupo, empezá de a dos o buscá a alguien que te oriente. A tu ritmo.</p></div><div class="paths"><article class="path"><span class="path-icon">${icon('people')}</span><span class="number">01 / EXPLORÁ</span><h3>Un plan. Tu gente.</h3><p>Caminatas, deporte, camping o una buena charla. Encontrá grupos con intereses en común y un motivo para salir.</p><a class="text-link" href="#/community">Explorar grupos <span>↗</span></a></article><article class="path"><span class="path-icon">${icon('buddy')}</span><span class="number">02 / CONECTÁ</span><h3>De a dos está bien.</h3><p>Los grupos grandes no son para todos. Conocé a una persona, compartí una actividad y dejá que la confianza llegue a su tiempo.</p><a class="text-link" href="#/community/uno-a-uno">Encontrar compañía <span>↗</span></a></article><article class="path"><span class="path-icon">${icon('compass')}</span><span class="number">03 / AVANZÁ</span><h3>Una mirada que guía.</h3><p>Conversá con un mentor sobre tus objetivos, las preguntas que te hacés y ese próximo paso que querés dar.</p><a class="text-link" href="#/community/mentores">Explorar mentoría <span>↗</span></a></article></div><div class="info-strip">${icon('shield')}<span>Vos elegís con quién conectar. Las conversaciones uno a uno empiezan cuando ambas personas aceptan.</span></div></div></section>
 <section class="section"><div class="wrap"><div class="mentor-banner"><div class="mentor-art" aria-hidden="true"><div class="orbits"><i class="orbit-dot"></i><i class="orbit-dot second"></i><span>↗</span></div></div><div class="mentor-copy"><div class="eyebrow">MENTORÍA CON INTENCIÓN</div><h2>El siguiente paso<br>se ve mejor<br>con perspectiva.</h2><p>No necesitás tener todas las respuestas. Un mentor puede ayudarte a ordenar tus ideas, reconocer posibilidades y definir un camino propio.</p><a class="button ghost" href="#/community/mentores">Encontrá orientación <span>↗</span></a></div></div><div class="quote-band"><p>No tenés que convertirte en otra persona.<br>Podés empezar por acercarte más a vos.</p><span>EL ESPÍRITU TREKSOR</span></div></div></section>
 <section class="section" style="padding-top:0"><div class="wrap"><div class="faq"><div class="eyebrow">ANTES DE EMPEZAR</div><h2>Un poco más de claridad.</h2><details><summary>¿Necesito experiencia para participar?</summary><p>No. Podés buscar actividades y personas con un ritmo similar al tuyo. Antes de unirte a una actividad, revisá su descripción y hablá con quien la organiza sobre el nivel y lo que necesitás llevar.</p></details><details><summary>¿Y si los grupos grandes me incomodan?</summary><p>El espacio Uno a uno existe para eso. Elegís tus intereses, tu ciudad y tu ritmo; después enviás una invitación. Solo se abre una conversación si la otra persona acepta. No hay obligación de reunirse ni de seguir conversando.</p></details><details><summary>¿Puedo usar mi cuenta de la app?</summary><p>Sí. La web usa las cuentas de Treksor. Entrá con el mismo correo y contraseña y completá tu perfil comunitario. Tu perfil solo aparece en Uno a uno cuando activás esa opción.</p></details><details><summary>¿Cómo funciona el contacto con un mentor?</summary><p>Cuando haya mentores aprobados, podrás explorar sus perfiles y enviar una presentación con tu objetivo. Si aceptan, se habilita una conversación privada para acordar disponibilidad, modalidad y condiciones. La web no procesa pagos ni confirma sesiones automáticamente.</p></details><details><summary>¿Por qué puede que todavía no vea grupos en mi ciudad?</summary><p>La comunidad está comenzando. Los grupos se crean por personas reales: si no encontrás uno cerca, podés proponer el primero. Mostramos únicamente perfiles y actividades publicados, sin llenar el espacio de participantes ficticios.</p></details></div></div></section>`;}
function renderEcosystem(){return pageTop('EL ECOSISTEMA TREKSOR','Cuatro dimensiones.<br>Una vida propia.','No se trata de hacerlo todo. Se trata de encontrar qué necesitás hoy y dar un próximo paso con intención.')+`<section class="section ecosystem-intro" style="padding-top:20px"><div class="wrap">${pillarData.map((p,i)=>`<article class="ecosystem-row"><span class="number">0${i+1}</span><div><h2>${p.name}</h2><p>${p.text}</p></div><div class="practice"><div class="eyebrow">${p.label}</div><h3>${p.practice}</h3><p>${p.description}</p><button class="text-link" data-action="practice" data-id="${i}">Probá este primer paso <span>↗</span></button></div></article>`).join('')}<div class="notice spaced">Las propuestas de bienestar son generales. Adaptalas a tu situación y a las indicaciones de tus profesionales cuando corresponda.</div><div class="quote-band"><p>Tu desarrollo es personal.<br>El camino puede ser compartido.</p><a class="button" href="#/community">Explorá Community ↗</a></div></div></section>`;}
function communityShell(tab){return pageTop('TREKSOR / COMMUNITY','Encontrá tu gente.<br>A tu manera.','Actividades que te mueven. Personas con las que conectás. Un espacio para pertenecer, sin dejar de ser vos.',tab==='grupos'?`<button class="button ghost" data-action="create-group">Proponer un grupo <span>＋</span></button>`:'')+`<section class="community-body"><div class="wrap"><nav class="tabs" aria-label="Formas de conectar"><a class="tab ${tab==='grupos'?'active':''}" href="#/community">${icon('people')} Grupos</a><a class="tab ${tab==='buddy'?'active':''}" href="#/community/uno-a-uno">${icon('buddy')} Uno a uno <small>A TU RITMO</small></a><a class="tab ${tab==='mentores'?'active':''}" href="#/community/mentores">${icon('compass')} Mentores</a></nav><div id="community-results"><div class="loading">Buscando tu próximo paso…</div></div></div></section>`;}
function filterForm(tab){const f=state.filters;const cats=tab==='mentores'?pillarData.map(p=>p.name):categories;return `<form class="filters" id="filters"><label><span class="filter-label">${tab==='grupos'?'BUSCAR UN GRUPO':'BUSCAR POR NOMBRE'}</span><input name="q" value="${esc(f.q)}" maxlength="80" placeholder="${tab==='grupos'?'Una actividad, un interés…':'¿A quién buscás?'}"></label><label><span class="filter-label">CIUDAD</span><input name="city" value="${esc(f.city)}" maxlength="100" placeholder="Tu ciudad"></label><label><span class="filter-label">${tab==='mentores'?'PILAR':'INTERÉS'}</span><select name="category"><option value="">Todos</option>${cats.map(c=>`<option ${f.category===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="button ghost" type="submit">Buscar ↗</button></form>`;}
async function renderCommunity(tab,version){
 const f=state.filters;let html='';
 if(tab!=='grupos'&&!state.user){html=`<div class="path-description"><div><h3>${tab==='buddy'?'Una persona. Un plan sencillo.':'Orientación para tu próximo paso.'}</h3><p>${tab==='buddy'?'Un café, una caminata o una actividad compartida. Podés empezar con una conversación y decidir después. Sin exposición ni presión.':'Explorá personas que quieran compartir su experiencia. Presentate, contá tu objetivo y acordá los siguientes pasos directamente con tu mentor.'}</p></div></div>`+empty('Primero, un espacio de confianza.','Entrá con tu cuenta de Treksor para ver perfiles y enviar invitaciones. Tu correo no se muestra a otras personas.',`<button class="button" data-action="login">Entrar a la comunidad ↗</button>`,tab==='buddy'?'buddy':'compass');}
 else if(tab==='grupos'){
  let request=db.from('web_groups').select('*').order('created_at',{ascending:false}).limit(60);if(f.q)request=request.ilike('title',`%${f.q}%`);if(f.city)request=request.ilike('city',`%${f.city}%`);if(categories.includes(f.category))request=request.eq('category',f.category);
  const groups=await query(request);html=filterForm(tab)+`<div class="chips">${categories.map(c=>`<button class="chip ${f.category===c?'active':''}" data-action="category" data-id="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="result-top"><span>${groups.length} ${groups.length===1?'grupo encontrado':'grupos encontrados'}</span><span><i class="status-dot"></i> Conexiones reales, a tu ritmo</span></div>`+(groups.length?`<div class="card-grid">${groups.map(groupCard).join('')}</div>`:empty(f.q||f.city||f.category?'Tu próximo grupo puede empezar con vos.':'Las buenas historias empiezan con un primer plan.',f.q||f.city||f.category?'Todavía no hay grupos con estos filtros. Probá otra búsqueda o proponé uno en tu ciudad.':'La comunidad está dando sus primeros pasos. Proponé una caminata, un encuentro o una actividad y abrí un espacio para quienes comparten tus intereses.',`<div class="inline-actions"><button class="button" data-action="create-group">Crear un grupo <span>＋</span></button>${f.q||f.city||f.category?'<button class="text-link" data-action="clear-filters">Limpiar filtros</button>':''}</div>`,'people'))+`<div class="info-strip">${icon('shield')}<span>Antes de encontrarte con un grupo, conversá sobre el nivel de la actividad y elegí un punto de encuentro público.</span></div>`;
 }else if(tab==='buddy'){
  let request=db.from('web_profiles').select('*').eq('discoverable',true).neq('user_id',state.user.id).order('created_at',{ascending:false}).limit(60);if(f.q)request=request.ilike('display_name',`%${f.q}%`);if(f.city)request=request.ilike('city',`%${f.city}%`);if(categories.includes(f.category))request=request.contains('interests',[f.category]);
  const people=await query(request);html=`<div class="path-description"><div><h3>Una persona. Un plan sencillo.</h3><p>No tenés que entrar en un grupo para sentirte parte. Empezá con una caminata o un café, a tu ritmo. Vos decidís cuándo conversar y si querés encontrarte.</p></div><button class="button ghost small" data-action="profile">${state.profile?.discoverable?'Editar mi perfil':'Quiero aparecer aquí'} ↗</button></div>`+filterForm(tab)+`<div class="result-top"><span>${people.length} ${people.length===1?'persona disponible':'personas disponibles'}</span><span>Invitación → aceptación → conversación</span></div>`+(people.length?`<div class="card-grid">${people.map(personCard).join('')}</div>`:empty('Tu gente puede estar por llegar.','Todavía no hay perfiles disponibles con estos filtros. Podés activar el tuyo para que otras personas con intereses similares te encuentren.',`<div class="inline-actions"><button class="button" data-action="profile">Preparar mi perfil ↗</button><button class="text-link" data-action="clear-filters">Limpiar filtros</button></div>`,'buddy'))+`<div class="info-strip">${icon('shield')}<span>Tu correo y tu ubicación exacta permanecen privados. Podés ocultar tu perfil, rechazar invitaciones o bloquear contactos cuando quieras.</span></div>`;
 }else{
  let request=db.from('web_mentors').select('*,profile:web_profiles(display_name,city,bio)').eq('approved',true).order('created_at',{ascending:false}).limit(60);if(pillarData.some(p=>p.name===f.category))request=request.eq('specialty',f.category);
  const all=await query(request);const mentors=all.filter(m=>m.profile&&(!f.city||m.profile.city.toLowerCase().includes(f.city.toLowerCase()))&&(!f.q||m.profile.display_name.toLowerCase().includes(f.q.toLowerCase())));
  html=`<div class="path-description"><div><h3>Una conversación puede abrir un camino.</h3><p>Elegí un pilar, conocé la experiencia de cada mentor y contale qué querés trabajar. La disponibilidad y las condiciones se acuerdan entre ustedes.</p></div><button class="button ghost small" data-action="apply-mentor">Quiero ser mentor ↗</button></div>`+filterForm(tab)+`<div class="result-top"><span>${mentors.length} ${mentors.length===1?'mentor disponible':'mentores disponibles'}</span><span>Perfiles revisados por Treksor</span></div>`+(mentors.length?`<div class="card-grid">${mentors.map(mentorCard).join('')}</div>`:empty('Estamos construyendo nuestra red de mentores.','Cuando los primeros perfiles sean revisados, aparecerán acá. Si tenés experiencia para compartir, podés enviar tu postulación.',`<button class="button" data-action="apply-mentor">Postularme como mentor ↗</button>`,'compass'))+`<div class="info-strip">${icon('shield')}<span>La mentoría ofrece orientación y acompañamiento. No sustituye atención médica o psicológica; la aprobación del perfil no equivale a una acreditación profesional.</span></div>`;
 }
 if(version===state.routeVersion)$('#community-results').innerHTML=html;
}
function groupCard(g){return `<article class="card"><div class="card-banner">${icon(g.category==='Hiking'||g.category==='Camping'?'mountain':g.category==='Café y charla'?'coffee':'people')}<span>${esc(g.category)}</span></div><div class="card-content"><div class="card-meta"><span>⌾ ${esc(g.city)}</span><span>${g.size_style==='small'?'Formato íntimo':'Grupo abierto'}</span></div><h3>${esc(g.title)}</h3><p>${esc(g.description.slice(0,145))}${g.description.length>145?'…':''}</p><div class="card-foot"><span>Un interés en común</span><a class="text-link" href="#/grupo/${g.id}">Conocer el grupo ↗</a></div></div></article>`;}
function personCard(p){return `<article class="card"><div class="card-content"><div class="profile-card-top">${avatar(p.display_name)}<div><h3>${esc(p.display_name)}</h3><p>⌾ ${esc(p.city||'Ciudad sin indicar')}</p></div></div><p>${esc(p.bio||'Me gustaría compartir actividades y conocer gente a mi ritmo.')}</p><div class="chips">${p.interests.map(i=>`<span class="chip">${esc(i)}</span>`).join('')}</div><div class="card-foot"><span>Ritmo ${esc(p.pace.toLowerCase())}</span><button class="text-link" data-action="invite" data-id="${p.user_id}">Conectar ↗</button></div></div></article>`;}
function mentorCard(m){return `<article class="card"><div class="card-content"><div class="profile-card-top">${avatar(m.profile.display_name)}<div><h3>${esc(m.profile.display_name)}</h3><p>${esc(m.specialty)} · ${esc(m.format)}</p></div></div><h3 style="font-size:18px">${esc(m.headline)}</h3><p>${esc(m.description.slice(0,160))}${m.description.length>160?'…':''}</p><div class="card-foot"><span>${esc(m.profile.city||'Online')}</span><button class="text-link" data-action="mentor-detail" data-id="${m.user_id}">Ver perfil ↗</button></div></div></article>`;}
function authDialog(mode='login'){
 if(!db){toast('No se pudo cargar la conexión. Actualizá la página.');return;}
 const signup=mode==='signup';state.dialogContext={mode};
 openDialog(signup?'Tu próximo paso empieza acá.':'Qué bueno verte por acá.',`<p class="lead">${signup?'Creá tu cuenta de Treksor. Después podrás elegir cómo participar.':'Usá el mismo correo y contraseña de la app Treksor.'}</p><form id="auth-form" class="form-grid">${signup?'<label>Tu nombre<input name="name" autocomplete="given-name" minlength="2" maxlength="60" required placeholder="¿Cómo te llamás?"></label>':''}<label>Correo electrónico<input name="email" type="email" autocomplete="email" required maxlength="254" placeholder="vos@ejemplo.com"></label><label>Contraseña<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="${signup?'8':'1'}" maxlength="128" placeholder="${signup?'Al menos 8 caracteres':'Tu contraseña'}"></label>${signup?'<label class="checkbox"><input type="checkbox" name="adult" required><span>Tengo 18 años o más y me comprometo a participar con respeto. <button class="text-link" type="button" data-action="principles">Leer convivencia</button></span></label>':''}<div class="form-error"></div><button class="button" type="submit">${signup?'Crear cuenta':'Entrar'} <span>↗</span></button><p class="helper">${signup?'Te enviaremos un correo de confirmación. Tu email nunca se publica en Community.':'Si tu cuenta usa acceso social y todavía no tiene contraseña, configurala desde la app antes de entrar aquí.'}</p></form><div class="auth-switch">${signup?'¿Ya tenés cuenta?':'¿Primera vez en Treksor?'}<button data-action="${signup?'login':'signup'}">${signup?'Entrar':'Crear cuenta'}</button></div>`,'TU ESPACIO TREKSOR');
}
function profileDialog(){if(!needUser())return;const p=state.profile||{display_name:state.user.user_metadata?.display_name||'',city:'',bio:'',interests:[],pace:'Tranquilo',discoverable:false};
 openDialog('Tu perfil. Tu ritmo.',`<p class="lead">Mostrá solo lo que te resulte cómodo. La visibilidad en Uno a uno es opcional.</p><form id="profile-form" class="form-grid"><div class="form-row"><label>Nombre público<input name="display_name" value="${esc(p.display_name)}" minlength="2" maxlength="60" required placeholder="Tu nombre o apodo"></label><label>Ciudad<input name="city" value="${esc(p.city)}" minlength="2" maxlength="100" required placeholder="Solo la ciudad, sin dirección"></label></div><label>Sobre vos<textarea name="bio" maxlength="600" placeholder="Qué disfrutás y qué te gustaría compartir…">${esc(p.bio)}</textarea></label><label>Tu ritmo<select name="pace">${['Tranquilo','Intermedio','Activo'].map(x=>`<option ${x===p.pace?'selected':''}>${x}</option>`).join('')}</select></label><fieldset style="border:0;padding:0;margin:0"><legend class="helper" style="margin-bottom:12px">Tus intereses</legend><div class="form-row">${categories.map(x=>`<label class="checkbox"><input type="checkbox" name="interests" value="${esc(x)}" ${p.interests.includes(x)?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div></fieldset><hr><label class="checkbox"><input type="checkbox" name="discoverable" ${p.discoverable?'checked':''}><span>Quiero aparecer en Uno a uno y recibir invitaciones de otras personas.</span></label><p class="helper">Tu nombre, ciudad, bio, intereses y ritmo se mostrarán a miembros de Treksor si activás esta opción. También se comparte tu perfil con tus contactos y si sos mentor aprobado.</p><div class="form-error"></div><button class="button" type="submit">Guardar mi perfil ↗</button></form>`,'COMMUNITY / MI PERFIL');
}
function groupDialog(group=null){if(!needProfile())return;state.dialogContext={group};openDialog(group?'Dale forma al próximo encuentro.':'Un buen plan empieza con vos.',`<p class="lead">Creá un espacio alrededor de una actividad. Compartí los detalles del encuentro con el grupo, sin publicar datos personales.</p><form id="group-form" class="form-grid"><label>Nombre del grupo<input name="title" required minlength="4" maxlength="90" value="${esc(group?.title||'')}" placeholder="Por ejemplo: Caminatas tranquilas por Brisbane"></label><div class="form-row"><label>Actividad<select name="category">${categories.map(c=>`<option ${group?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Ciudad<input name="city" required minlength="2" maxlength="100" value="${esc(group?.city||state.profile.city)}" placeholder="Ciudad"></label></div><label>¿Qué te gustaría compartir?<textarea name="description" minlength="10" maxlength="1200" required placeholder="Contá la idea, el nivel y para quién es el grupo…">${esc(group?.description||'')}</textarea></label><label>Formato<select name="size_style"><option value="small">Íntimo: preferimos encuentros pequeños</option><option value="open" ${group?.size_style==='open'?'selected':''}>Abierto: todos los tamaños son bienvenidos</option></select></label><label>Próxima propuesta (opcional)<input name="next_activity" maxlength="300" value="${esc(group?.next_activity||'')}" placeholder="Por ejemplo: caminata el sábado por la mañana"></label><p class="helper">El formato expresa una preferencia; no establece un límite automático de participantes. El grupo será visible para visitantes y miembros.</p><div class="form-error"></div><button class="button" type="submit">${group?'Guardar cambios':'Crear el grupo'} ↗</button></form>`,'COMMUNITY / GRUPOS');}
async function inviteDialog(id,kind='buddy'){if(!needProfile())return;if(id===state.user.id){toast('Este es tu propio perfil.');return;}const p=await query(db.from('web_profiles').select('display_name').eq('user_id',id).single());const existing=await query(db.from('web_connections').select('id').eq('kind',kind).or(`and(from_user.eq.${state.user.id},to_user.eq.${id}),and(from_user.eq.${id},to_user.eq.${state.user.id})`).maybeSingle());if(existing){closeDialog();go('/conexion/'+existing.id);return;}state.dialogContext={id,kind};openDialog(kind==='mentor'?'Presentá tu próximo objetivo.':'Todo empieza con un hola.',`<p class="lead">${kind==='mentor'?'Contale a':'Presentate a'} <strong>${esc(p.display_name)}</strong>. La conversación se habilita cuando acepte tu invitación.</p><form id="invite-form" class="form-grid"><label>${kind==='mentor'?'¿En qué te gustaría recibir orientación?':'¿Qué actividad te gustaría compartir?'}<textarea name="introduction" minlength="10" maxlength="1000" required placeholder="Contá un poco sobre vos y lo que estás buscando…"></textarea></label><p class="helper">No incluyas teléfono, dirección ni información sensible. Podés conversar dentro de Treksor después de la aceptación.</p><div class="form-error"></div><button class="button" type="submit">Enviar ${kind==='mentor'?'solicitud':'invitación'} ↗</button></form>`,'COMMUNITY / '+(kind==='mentor'?'MENTORÍA':'UNO A UNO'));}
async function applyMentorDialog(){if(!needProfile())return;const existing=await query(db.from('web_mentors').select('approved').eq('user_id',state.user.id).maybeSingle());if(existing){openDialog(existing.approved?'Tu perfil está publicado.':'Tu postulación está en revisión.',`<div class="dialog-text"><p>${existing.approved?'Podés recibir solicitudes de mentoría en Mi espacio.':'Treksor revisará la experiencia y la información que compartiste antes de publicar tu perfil. Todavía no sos visible en el directorio.'}</p><a class="button" href="#/espacio" data-action="close">Ir a Mi espacio ↗</a><button class="text-link" data-action="withdraw-mentor">Retirar mi ${existing.approved?'perfil':'postulación'}</button></div>`,'COMMUNITY / MENTORES');return;}
 openDialog('Compartí lo que aprendiste.',`<p class="lead">Contanos tu experiencia. Tu perfil solo se publicará después de una revisión por Treksor.</p><form id="mentor-form" class="form-grid"><label>Una frase sobre cómo acompañás<input name="headline" required minlength="5" maxlength="100" placeholder="Por ejemplo: convertir objetivos en hábitos sostenibles"></label><div class="form-row"><label>Pilar<select name="specialty">${pillarData.map(p=>`<option>${p.name}</option>`).join('')}</select></label><label>Modalidad<select name="format"><option>Online</option><option>Presencial</option><option>Ambos</option></select></label></div><label>¿En qué podés ayudar?<textarea name="description" required minlength="20" maxlength="1200" placeholder="Tu enfoque, los temas que abordás y los límites de tu acompañamiento…"></textarea></label><label>Experiencia y referencias<textarea name="experience" required minlength="10" maxlength="1200" placeholder="Experiencia relevante, formación y enlaces públicos que ayuden a revisarla. No incluyas documentos de identidad."></textarea></label><label class="checkbox"><input type="checkbox" required><span>La información es verdadera y entiendo que Treksor revisará mi postulación.</span></label><div class="form-error"></div><button class="button" type="submit">Enviar postulación ↗</button></form>`,'COMMUNITY / MENTORES');}
async function mentorDetail(id){if(!needUser())return;const m=await query(db.from('web_mentors').select('*,profile:web_profiles(display_name,city)').eq('user_id',id).eq('approved',true).single());if(!m.profile)throw new Error('Unavailable');openDialog(esc(m.profile.display_name),`<div class="dialog-text"><span class="tag">${esc(m.specialty)} · ${esc(m.format)} · ${esc(m.profile.city)}</span><h3>${esc(m.headline)}</h3><p style="white-space:pre-wrap">${esc(m.description)}</p><h3>Experiencia compartida</h3><p style="white-space:pre-wrap">${esc(m.experience)}</p><div class="notice">Consultá disponibilidad, honorarios si los hubiera y alcance del acompañamiento antes de acordar una sesión.</div><button class="button" data-action="mentor-invite" data-id="${id}">Contactar con este mentor ↗</button><button class="text-link" data-action="report-user" data-id="${id}">Reportar este perfil</button></div>`,'COMMUNITY / PERFIL DE MENTOR');}
async function renderDashboard(version){
 if(!state.user){main.innerHTML=pageTop('MI ESPACIO','Tu lugar en Treksor.','Tus grupos, tus conexiones y tu próximo paso, juntos.')+`<section class="dashboard"><div class="wrap">${empty('Entrá para continuar.','Usá tu cuenta de Treksor y reuní tus conexiones en un solo lugar.','<button class="button" data-action="login">Entrar ↗</button>')}</div></section>`;return;}
 const [connections,members,owned,mentor,blocks]=await Promise.all([query(db.from('web_connections').select('*').order('created_at',{ascending:false}).limit(100)),query(db.from('web_group_members').select('group:web_groups(*)').eq('user_id',state.user.id)),query(db.from('web_groups').select('*').eq('owner_id',state.user.id)),query(db.from('web_mentors').select('*').eq('user_id',state.user.id).maybeSingle()),query(db.from('web_blocks').select('*').eq('blocker_id',state.user.id))]);
 const names=await getNames(connections.flatMap(c=>[c.from_user,c.to_user]));const groups=[...new Map([...owned,...members.map(m=>m.group).filter(Boolean)].map(g=>[g.id,g])).values()];const p=state.profile;const incoming=connections.filter(c=>c.to_user===state.user.id&&c.status==='pending');const other=connections.filter(c=>!incoming.includes(c));
 const html=pageTop('TREKSOR / MI ESPACIO',p?`Hola, ${esc(p.display_name)}.`:'Tu camino empieza con vos.','Elegí con quién compartirlo. Todo lo que conectás, en un mismo lugar.')+`<section class="dashboard"><div class="wrap dashboard-grid"><aside class="profile-panel">${avatar(p?.display_name||'T',true)}<h3>${esc(p?.display_name||'Completá tu perfil')}</h3><p>${esc(p?.city||'Agregá tu ciudad e intereses.')}</p><div class="spaced"><span class="tag">${p?.discoverable?'Visible en Uno a uno':'Perfil discreto'}</span></div><button class="button ghost small" data-action="profile">${p?'Editar perfil':'Crear perfil'} ↗</button><button class="text-link" data-action="apply-mentor">${mentor?(mentor.approved?'Mi perfil de mentor':'Postulación en revisión'):'Quiero ser mentor'} ↗</button>${state.admin?'<a class="text-link" href="#/gestion">Gestión de comunidad ↗</a>':''}<hr style="border:0;border-top:1px solid var(--line);margin:23px 0 6px"><button class="text-link" data-action="logout">Cerrar sesión ↗</button></aside><div><section class="dash-section"><div class="dash-title"><h2>Invitaciones para vos</h2><button class="text-link" data-action="refresh">Actualizar ↻</button></div>${incoming.length?incoming.map(c=>connectionRow(c,names,true)).join(''):'<div class="simple-empty">Todavía no tenés invitaciones nuevas. Vos elegís qué conexiones aceptar.</div>'}</section><section class="dash-section"><div class="dash-title"><h2>Mis conexiones</h2><a class="text-link" href="#/community/uno-a-uno">Explorar ↗</a></div>${other.length?other.map(c=>connectionRow(c,names,false)).join(''):'<div class="simple-empty">Una conversación puede ser el comienzo. <a href="#/community/uno-a-uno">Encontrá compañía</a> o <a href="#/community/mentores">explorá mentoría</a>.</div>'}</section><section class="dash-section"><div class="dash-title"><h2>Mis grupos</h2><button class="text-link" data-action="create-group">Crear un grupo ＋</button></div>${groups.length?groups.map(g=>`<div class="list-row"><div><span class="tag">${esc(g.category)} · ${g.owner_id===state.user.id?'Organizás vos':'Sos parte'}</span><h3>${esc(g.title)}</h3><p>${esc(g.city)}</p></div><a class="button small ghost" href="#/grupo/${g.id}">Abrir grupo ↗</a></div>`).join(''):'<div class="simple-empty">Todavía no sos parte de un grupo. <a href="#/community">Encontrá un plan</a> o proponé el primero.</div>'}</section>${blocks.length?`<section class="dash-section"><div class="dash-title"><h2>Contactos bloqueados</h2></div>${blocks.map((b,i)=>`<div class="list-row"><p>Contacto bloqueado ${i+1} · ${date(b.created_at)}</p><button class="button small ghost" data-action="unblock" data-id="${b.blocked_id}">Desbloquear</button></div>`).join('')}</section>`:''}</div></div></section>`;
 if(version===state.routeVersion)main.innerHTML=html;
}
async function getNames(ids){const unique=[...new Set(ids)];if(!unique.length)return {};const profiles=await query(db.from('web_profiles').select('user_id,display_name').in('user_id',unique));return Object.fromEntries(profiles.map(p=>[p.user_id,p.display_name]));}
const statusLabels={pending:'Invitación pendiente',accepted:'Conexión aceptada',declined:'Invitación rechazada',closed:'Conexión cerrada'};
function connectionRow(c,names,incoming){const other=c.from_user===state.user.id?c.to_user:c.from_user;return `<div class="list-row"><div class="row-content"><span class="tag">${c.kind==='mentor'?'Mentoría':'Uno a uno'} · ${statusLabels[c.status]}</span><h3>${esc(names[other]||'Miembro de Treksor')}</h3><p>${esc(c.introduction.slice(0,125))}${c.introduction.length>125?'…':''}</p></div><div class="actions">${incoming?btn('Aceptar','accept',c.id)+btn('Rechazar','decline',c.id,'ghost'):''}<a class="button small ghost" href="#/conexion/${c.id}">${c.status==='accepted'?'Conversar':'Ver detalle'} ↗</a></div></div>`;}
async function renderGroup(id,version){
 const g=await query(db.from('web_groups').select('*').eq('id',id).maybeSingle());if(!g){if(version===state.routeVersion)main.innerHTML=pageTop('COMMUNITY','Este grupo ya no está disponible.','Podés seguir explorando otros intereses.')+`<div class="wrap section"><a class="button" href="#/community">Volver a grupos ↗</a></div>`;return;}
 const own=g.owner_id===state.user?.id;let member=null,posts=[];if(state.user){member=await query(db.from('web_group_members').select('user_id').eq('group_id',id).eq('user_id',state.user.id).maybeSingle());if(member||own)posts=await query(db.from('web_group_posts').select('*').eq('group_id',id).order('created_at',{ascending:false}).limit(60));}
 const joined=own||!!member;const names=await (state.user?getNames(posts.map(p=>p.user_id)):Promise.resolve({}));const html=`<section class="section" style="padding-top:45px"><div class="wrap"><a class="back-link" href="#/community">← Volver a grupos</a><div class="detail-head"><div class="eyebrow spaced">COMMUNITY / ${esc(g.category)}</div><h1>${esc(g.title)}</h1><div class="card-meta"><span>⌾ ${esc(g.city)}</span><span>${g.size_style==='small'?'Encuentros en formato íntimo':'Grupo abierto'}</span></div></div><div class="detail-grid"><div><div class="detail-panel"><h3>Lo que nos reúne</h3><p>${esc(g.description)}</p>${g.next_activity?`<h3 class="spaced">La próxima propuesta</h3><p>${esc(g.next_activity)}</p>`:''}</div><div class="detail-panel"><div class="dash-title"><h3>Conversaciones del grupo</h3>${joined?'<button class="text-link" data-action="refresh">Actualizar ↻</button>':''}</div>${joined?`<div class="posts">${posts.length?posts.reverse().map(p=>`<article class="post${p.user_id===state.user.id?' mine':''}"><small>${esc(names[p.user_id]||(p.user_id===state.user.id?'Vos':'Miembro del grupo'))} · ${date(p.created_at)}</small><p>${esc(p.body)}</p></article>`).join(''):'<div class="simple-empty">El grupo todavía no tiene mensajes. Podés proponer el primer plan.</div>'}</div><form id="post-form" class="post-form" data-id="${id}"><label>Compartí una idea<textarea name="body" required minlength="1" maxlength="2000" placeholder="Una propuesta, una pregunta, un hola…"></textarea></label><button type="submit" class="button">Publicar ↗</button><div class="form-error"></div></form>`:'<p>Unite al grupo para leer y participar de las conversaciones.</p>'}</div></div><aside><div class="detail-panel"><div class="eyebrow">UN INTERÉS EN COMÚN</div><h3>${joined?'Ya sos parte.':'Un lugar para compartir.'}</h3><p>${own?'Creaste este grupo. Podés actualizar su descripción y su próxima propuesta.':'Cada grupo define sus actividades y su ritmo. Preguntá lo que necesites antes de participar.'}</p>${own?btn('Editar grupo ↗','edit-group',id,'ghost'):member?btn('Salir del grupo','leave-group',id,'ghost'):btn('Unirme al grupo ↗','join-group',id)}</div><div class="info-strip">${icon('shield')}<span>Elegí lugares públicos para los primeros encuentros. No publiques direcciones personales ni datos sensibles.</span></div>${state.user?`<button class="text-link" data-action="report-group" data-id="${id}">Reportar grupo</button>`:''}${own?`<div class="spaced"><button class="text-link" data-action="delete-group-confirm" data-id="${id}">Cerrar y eliminar grupo</button></div>`:''}</aside></div></div></section>`;if(version===state.routeVersion)main.innerHTML=html;
}
async function renderConnection(id,version){
 if(!state.user){await renderDashboard(version);return;}const c=await query(db.from('web_connections').select('*').eq('id',id).maybeSingle());if(!c){if(version===state.routeVersion)main.innerHTML=pageTop('MI ESPACIO','Conexión no disponible.','Puede que no tengas acceso a esta conversación.')+`<div class="wrap section"><a class="button" href="#/espacio">Volver a Mi espacio ↗</a></div>`;return;}
 const other=c.from_user===state.user.id?c.to_user:c.from_user;const [names,messages,blocks]=await Promise.all([getNames([other]),query(db.from('web_messages').select('*').eq('connection_id',id).order('created_at',{ascending:false}).limit(100)),query(db.from('web_blocks').select('*').or(`and(blocker_id.eq.${state.user.id},blocked_id.eq.${other}),and(blocker_id.eq.${other},blocked_id.eq.${state.user.id})`))]);const blocked=!!blocks.length;const name=names[other]||'Miembro de Treksor';const html=`<section class="section" style="padding-top:45px"><div class="wrap prose"><a class="back-link" href="#/espacio">← Volver a Mi espacio</a><div class="detail-head"><div class="eyebrow spaced">${c.kind==='mentor'?'MENTORÍA':'UNO A UNO'} / ${statusLabels[c.status]}</div><h1>${esc(name)}</h1></div><div class="connection-summary"><span class="tag">La presentación inicial</span><p>${esc(c.introduction)}</p>${c.status==='pending'&&c.to_user===state.user.id&&!blocked?`<div class="conversation-actions">${btn('Aceptar y conversar','accept',id)}${btn('Rechazar','decline',id,'ghost')}</div>`:''}</div><div class="inline-actions"><button class="text-link" data-action="refresh">Actualizar conversación ↻</button></div><div class="posts">${messages.length?messages.reverse().map(m=>`<article class="post${m.sender_id===state.user.id?' mine':''}"><small>${m.sender_id===state.user.id?'Vos':esc(name)} · ${date(m.created_at)}</small><p>${esc(m.body)}</p></article>`).join(''):''}</div>${c.status==='accepted'&&!blocked?`<form id="message-form" class="post-form" data-id="${id}"><label>Tu mensaje<textarea name="body" required minlength="1" maxlength="2000" placeholder="Conversá a tu ritmo…"></textarea></label><button class="button" type="submit">Enviar ↗</button><div class="form-error"></div></form>`:`<div class="notice">${blocked?'Esta conexión tiene una restricción de contacto. No se pueden enviar mensajes.':c.status==='pending'?'La conversación se habilita cuando la invitación es aceptada.':c.status==='declined'?'La invitación fue rechazada. Respetá la decisión y seguí explorando otras conexiones.':'La conexión está cerrada. El historial queda disponible para vos.'}</div>`}<div class="conversation-actions spaced">${!blocked?btn('Bloquear contacto','block-confirm',other,'ghost'):''}${c.status==='accepted'||c.status==='pending'?btn('Cerrar conexión','close-connection-confirm',id,'ghost'):''}<button class="text-link" data-action="report-user" data-id="${other}">Reportar</button></div><div class="info-strip">${icon('shield')}<span>Las conversaciones son privadas entre participantes. No compartas datos sensibles y elegí un lugar público si deciden encontrarse.</span></div></div></section>`;if(version===state.routeVersion)main.innerHTML=html;
}
async function renderAdmin(version){
 if(!state.admin){if(version===state.routeVersion)main.innerHTML=pageTop('TREKSOR','Acceso reservado.','Este espacio es exclusivo para administradores de Treksor.')+`<div class="wrap section"><a class="button" href="#/espacio">Ir a Mi espacio ↗</a></div>`;return;}
 const [mentors,reports]=await Promise.all([query(db.from('web_mentors').select('*,profile:web_profiles(display_name,city)').eq('approved',false).order('created_at')),query(db.from('web_reports').select('*').eq('resolved',false).order('created_at'))]);const names=await getNames(reports.flatMap(r=>[r.reporter_id,r.target_user]).filter(Boolean));const html=pageTop('TREKSOR / GESTIÓN','Cuidar la comunidad.','Revisá postulaciones, experiencias y reportes antes de tomar una decisión.')+`<div class="wrap dashboard"><section class="dash-section"><div class="dash-title"><h2>Postulaciones de mentores</h2><button class="text-link" data-action="refresh">Actualizar ↻</button></div>${mentors.length?mentors.map(m=>`<article class="detail-panel"><span class="tag">${esc(m.specialty)} · ${esc(m.format)}</span><h3>${esc(m.profile?.display_name||'Perfil')} — ${esc(m.headline)}</h3><p>${esc(m.description)}</p><h3 class="spaced">Experiencia y referencias</h3><p>${esc(m.experience)}</p><div class="notice spaced">Revisá identidad, experiencia, referencias y límites del acompañamiento antes de aprobar. No se envían comunicaciones externas desde esta pantalla.</div><div class="conversation-actions">${btn('Aprobar perfil','approve-mentor',m.user_id)}${btn('Eliminar postulación','reject-mentor-confirm',m.user_id,'ghost')}</div></article>`).join(''):'<div class="simple-empty">No hay postulaciones pendientes.</div>'}</section><section class="dash-section"><div class="dash-title"><h2>Reportes pendientes</h2></div>${reports.length?reports.map(r=>`<article class="detail-panel"><span class="tag">${date(r.created_at)}</span><h3>Reporte de ${esc(names[r.reporter_id]||'Miembro')}</h3><p>${esc(r.reason)}</p>${r.target_user?`<p class="spaced">Perfil reportado: ${esc(names[r.target_user]||r.target_user)}</p>`:''}${r.target_group?`<a class="text-link spaced" href="#/grupo/${r.target_group}">Revisar grupo ↗</a>`:''}<div class="conversation-actions">${btn('Marcar revisado','resolve-report',r.id,'ghost')}${r.target_user?btn('Retirar mentoría','revoke-mentor-confirm',r.target_user,'ghost'):''}${r.target_group?btn('Eliminar grupo','delete-group-confirm',r.target_group,'ghost'):''}</div></article>`).join(''):'<div class="simple-empty">No hay reportes pendientes.</div>'}</section></div>`;if(version===state.routeVersion)main.innerHTML=html;
}
function reportDialog(id,group=false){if(!needUser())return;state.dialogContext={id,group};openDialog('Ayudanos a cuidar este espacio.',`<p class="lead">Contanos qué pasó. El reporte será visible para vos y para los administradores de Treksor.</p><form id="report-form" class="form-grid"><label>Motivo del reporte<textarea name="reason" required minlength="10" maxlength="1500" placeholder="Describí la situación con el contexto necesario…"></textarea></label><div class="form-error"></div><button type="submit" class="button">Enviar reporte ↗</button></form>`,'COMMUNITY / CONVIVENCIA');}
function confirmDialog(title,text,action,id){openDialog(title,`<div class="dialog-text"><p>${text}</p><div class="inline-actions">${btn('Confirmar',action,id,'danger')}${btn('Cancelar','close','','ghost')}</div></div>`,'TREKSOR / CONFIRMAR');}
function principles(){openDialog('Un espacio que cuidamos entre todos.',`<div class="dialog-text"><h3>Respeto, sin presión</h3><p>Una invitación es una posibilidad, no una obligación. Respetá los tiempos, los límites y la decisión de no continuar. No se admite acoso, discriminación ni contenido sexual no solicitado.</p><h3>Encuentros con criterio</h3><p>Community está pensado para personas mayores de 18 años. Para los primeros encuentros, elegí lugares públicos, avisá a alguien de confianza y acordá antes el nivel y las condiciones de la actividad.</p><h3>Experiencia honesta</h3><p>No inventes identidad, experiencia ni acreditaciones. Los mentores deben explicar el alcance de lo que ofrecen. No envíes pagos ni documentos personales sin verificar las condiciones y a la otra persona.</p><h3>Tu control importa</h3><p>Podés ocultar tu perfil, rechazar invitaciones, cerrar conversaciones, bloquear contactos y reportar situaciones desde la web.</p></div>`,'COMMUNITY / CONVIVENCIA');}
function privacy(){openDialog('Tu espacio, con límites claros.',`<div class="dialog-text"><h3>Qué se comparte</h3><p>Los grupos y sus descripciones son visibles para visitantes. Los perfiles uno a uno son visibles para miembros cuando la persona activa esa opción. El perfil de un mentor se publica después de ser aprobado; tus contactos también pueden ver tu perfil.</p><h3>Qué se mantiene privado</h3><p>Tu correo de acceso no se muestra en Community. Las invitaciones y mensajes solo se muestran a sus participantes. Los reportes se muestran a quien los envía y a los administradores.</p><h3>Cómo se guardan tus datos</h3><p>Treksor utiliza Supabase para cuentas y datos de comunidad. La sesión se conserva en este navegador para que puedas seguir conectado; cerrá sesión en dispositivos compartidos. No publiques datos de salud, direcciones exactas ni información sensible en perfiles o grupos.</p><h3>Tus controles</h3><p>Desde Mi espacio podés editar u ocultar tu perfil, salir de grupos, retirar tu postulación de mentor y gestionar bloqueos. Cerrar una conexión conserva el historial; esta versión no incluye una eliminación completa de cuenta desde la web.</p></div>`,'TREKSOR / PRIVACIDAD');}
async function render(){const version=++state.routeVersion;const path=route();updateNav();document.querySelector('.header').classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');document.title=(path.startsWith('/community')?'Community':path==='/espacio'?'Mi espacio':path==='/ecosistema'?'Ecosistema':'Crecé a tu manera')+' — Treksor';try{
 if(path==='/'){main.innerHTML=renderHome();return;}if(path==='/ecosistema'){main.innerHTML=renderEcosystem();return;}
 if(!db)throw new Error('Connection unavailable');
 if(path.startsWith('/community')){const tab=path.endsWith('/uno-a-uno')?'buddy':path.endsWith('/mentores')?'mentores':'grupos';main.innerHTML=communityShell(tab);await renderCommunity(tab,version);return;}
 main.innerHTML='<div class="wrap section"><div class="loading">Preparando tu espacio…</div></div>';
 if(path==='/espacio')await renderDashboard(version);else if(path.startsWith('/grupo/'))await renderGroup(path.split('/')[2],version);else if(path.startsWith('/conexion/'))await renderConnection(path.split('/')[2],version);else if(path==='/gestion')await renderAdmin(version);else main.innerHTML=pageTop('TREKSOR','Este camino todavía no existe.','Volvé al inicio para encontrar tu próximo paso.')+'<div class="wrap section"><a href="#/" class="button">Volver al inicio ↗</a></div>';
 }catch(e){console.error('Treksor:',e?.code||e?.message);if(version===state.routeVersion){const target=$('#community-results')||main;target.innerHTML=`<div class="wrap section"><div class="page-error"><h3>No pudimos cargar este espacio.</h3><p>${errorText(e)}</p><button class="button ghost" data-action="refresh">Volver a intentar ↻</button></div></div>`;}}
}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
 if(el.tagName==='A'&&action==='close'){closeDialog();return;}event.preventDefault();
 try{
 if(action==='menu'){const opened=document.querySelector('.header').classList.toggle('menu-open');el.setAttribute('aria-expanded',String(opened));}
 else if(action==='close')closeDialog();else if(action==='login')authDialog();else if(action==='signup')authDialog('signup');else if(action==='profile')profileDialog();else if(action==='principles')principles();else if(action==='privacy')privacy();
 else if(action==='refresh')await render();else if(action==='create-group')groupDialog();else if(action==='edit-group'){const g=await query(db.from('web_groups').select('*').eq('id',id).single());groupDialog(g);}
 else if(action==='practice'){const p=pillarData[Number(id)];openDialog(p.practice,`<div class="dialog-text"><p>${p.description}</p><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><a class="button" href="#/community" data-action="close">Compartí el próximo paso ↗</a></div>`,p.name.toUpperCase());}
 else if(action==='category'){state.filters.category=state.filters.category===id?'':id;await render();}
 else if(action==='clear-filters'){state.filters={q:'',city:'',category:''};await render();}
 else if(action==='invite')await inviteDialog(id);else if(action==='mentor-invite')await inviteDialog(id,'mentor');else if(action==='apply-mentor')await applyMentorDialog();else if(action==='mentor-detail')await mentorDetail(id);
 else if(action==='report-user')reportDialog(id);else if(action==='report-group')reportDialog(id,true);
 else if(action==='block-confirm')confirmDialog('¿Bloquear este contacto?','No podrán enviarse nuevos mensajes ni invitaciones. Podés gestionar tus bloqueos desde Mi espacio.','block',id);
 else if(action==='close-connection-confirm')confirmDialog('¿Cerrar esta conexión?','No se podrán enviar nuevos mensajes. El historial se conserva. Esta acción no se revierte desde la web.','close-connection',id);
 else if(action==='delete-group-confirm')confirmDialog('¿Eliminar este grupo?','Se eliminarán el grupo, las inscripciones y sus conversaciones. Esta acción es permanente.','delete-group',id);
 else if(action==='reject-mentor-confirm')confirmDialog('¿Eliminar esta postulación?','El perfil no será publicado. La persona podrá enviar una nueva postulación más adelante.','reject-mentor',id);
 else if(action==='revoke-mentor-confirm')confirmDialog('¿Retirar esta mentoría?','Si tiene un perfil de mentor, dejará de aparecer en el directorio. No se elimina la cuenta ni el historial de conexiones.','reject-mentor',id);
 else{
  el.disabled=true;
  if(action==='logout'){const {error}=await db.auth.signOut();if(error)throw error;state.user=null;state.profile=null;state.admin=false;go('/');toast('Sesión cerrada.');}
  else if(action==='join-group'){if(!needProfile())return;await query(db.from('web_group_members').insert({group_id:id,user_id:state.user.id}));toast('Ya sos parte del grupo.');await render();}
  else if(action==='leave-group'){await query(db.from('web_group_members').delete().eq('group_id',id).eq('user_id',state.user.id));toast('Saliste del grupo.');await render();}
  else if(['accept','decline','close-connection'].includes(action)){const status=action==='accept'?'accepted':action==='decline'?'declined':'closed';await query(db.from('web_connections').update({status}).eq('id',id).select('id').single());closeDialog();toast(action==='accept'?'Conexión aceptada. Ya pueden conversar.':action==='decline'?'Invitación rechazada.':'Conexión cerrada.');await render();}
  else if(action==='block'){await query(db.from('web_blocks').insert({blocker_id:state.user.id,blocked_id:id}));closeDialog();toast('Contacto bloqueado.');await render();}
  else if(action==='unblock'){await query(db.from('web_blocks').delete().eq('blocker_id',state.user.id).eq('blocked_id',id));toast('Contacto desbloqueado.');await render();}
  else if(action==='withdraw-mentor'){await query(db.from('web_mentors').delete().eq('user_id',state.user.id));closeDialog();toast('Retiraste tu perfil de mentor.');await render();}
  else if(action==='approve-mentor'){await query(db.from('web_mentors').update({approved:true}).eq('user_id',id).select('user_id').single());toast('Perfil de mentor publicado.');await render();}
  else if(action==='reject-mentor'){await query(db.from('web_mentors').delete().eq('user_id',id));closeDialog();toast('Perfil de mentor retirado.');await render();}
  else if(action==='resolve-report'){await query(db.from('web_reports').update({resolved:true}).eq('id',id).select('id').single());toast('Reporte marcado como revisado.');await render();}
  else if(action==='delete-group'){await query(db.from('web_groups').delete().eq('id',id).select('id').single());closeDialog();toast('Grupo eliminado.');go(state.admin?'/gestion':'/espacio');}
 }
 }catch(e){toast(errorText(e));}finally{el.disabled=false;}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const data=new FormData(form);const val=name=>String(data.get(name)||'').trim();const button=$('button[type=submit]',form);const error=$('.form-error',form);if(error)error.textContent='';if(button)button.disabled=true;
 try{
  if(form.id==='filters'){state.filters={q:val('q').replace(/[%_]/g,''),city:val('city').replace(/[%_]/g,''),category:val('category')};await render();}
  else if(form.id==='auth-form'){
   const signup=state.dialogContext?.mode==='signup';const email=val('email'),password=String(data.get('password')||'');let result;
   if(signup)result=await db.auth.signUp({email,password,options:{data:{display_name:val('name'),adult_confirmed:true}}});else result=await db.auth.signInWithPassword({email,password});
   if(result.error)throw result.error;
   if(signup&&!result.data.session){openDialog('Revisá tu correo.',`<div class="dialog-text"><p>Si el registro puede completarse, recibirás un mensaje de confirmación. Abrí el enlace y después volvé acá para entrar con tu correo y contraseña.</p><p>Si ya tenías una cuenta, podés iniciar sesión directamente.</p><button class="button" data-action="login">Volver a entrar ↗</button></div>`,'TU CUENTA TREKSOR');}
   else{state.user=result.data.user;await loadProfile();closeDialog();go('/espacio');toast('Bienvenido a Treksor.');if(!state.profile)profileDialog();}
  }
  else if(form.id==='profile-form'){
   const payload={user_id:state.user.id,display_name:val('display_name'),city:val('city'),bio:val('bio'),pace:val('pace'),interests:data.getAll('interests'),discoverable:data.has('discoverable')};
   if(state.profile){const {user_id,...fields}=payload;await query(db.from('web_profiles').update(fields).eq('user_id',user_id).select().single());}else await query(db.from('web_profiles').insert(payload).select().single());await loadProfile();closeDialog();toast('Tu perfil quedó guardado.');await render();
  }
  else if(form.id==='group-form'){
   const payload={title:val('title'),description:val('description'),category:val('category'),city:val('city'),size_style:val('size_style'),next_activity:val('next_activity')};const editing=state.dialogContext?.group;const group=editing?await query(db.from('web_groups').update(payload).eq('id',editing.id).select().single()):await query(db.from('web_groups').insert({...payload,owner_id:state.user.id}).select().single());closeDialog();toast(editing?'Grupo actualizado.':'Tu grupo ya está creado.');go('/grupo/'+group.id);
  }
  else if(form.id==='invite-form'){const {id,kind}=state.dialogContext;const connection=await query(db.from('web_connections').insert({from_user:state.user.id,to_user:id,kind,introduction:val('introduction')}).select().single());closeDialog();toast('Invitación enviada dentro de Treksor.');go('/conexion/'+connection.id);}
  else if(form.id==='mentor-form'){await query(db.from('web_mentors').insert({user_id:state.user.id,headline:val('headline'),specialty:val('specialty'),format:val('format'),description:val('description'),experience:val('experience')}));closeDialog();toast('Postulación recibida. Queda pendiente de revisión.');go('/espacio');}
  else if(form.id==='post-form'){await query(db.from('web_group_posts').insert({group_id:form.dataset.id,user_id:state.user.id,body:val('body')}));toast('Mensaje publicado en el grupo.');await render();}
  else if(form.id==='message-form'){await query(db.from('web_messages').insert({connection_id:form.dataset.id,sender_id:state.user.id,body:val('body')}));toast('Mensaje enviado.');await render();}
  else if(form.id==='report-form'){const {id,group}=state.dialogContext;await query(db.from('web_reports').insert({reporter_id:state.user.id,target_user:group?null:id,target_group:group?id:null,reason:val('reason')}));closeDialog();toast('Reporte recibido por Treksor.');}
 }catch(e){formError(form,e);}finally{if(button)button.disabled=false;}
});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const rect=$('#dialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>{closeDialog();state.filters={q:'',city:'',category:''};window.scrollTo(0,0);render();});
$('#year').textContent=String(new Date().getFullYear());
(async()=>{await render();if(!db)return;try{const {data,error}=await db.auth.getSession();if(error)throw error;state.user=data.session?.user||null;await loadProfile();if(state.user)await render();}catch(e){toast('No pudimos recuperar la sesión. Volvé a entrar.');}db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.user=null;state.profile=null;state.admin=false;updateNav();if(route()!=='/')setTimeout(render,0);}else if(event==='SIGNED_IN'&&session?.user?.id!==state.user?.id){state.user=session.user;setTimeout(async()=>{try{await loadProfile();await render();}catch(e){toast(errorText(e));}},0);}});})();
